def revise_workshops(lessons):
    from prisoner_reading import revise_prisoner
    revise_prisoner(REVISIONS['uvidet-drugogo'])
    for lesson in lessons:
        if lesson['slug'] in REVISIONS:
            lesson.update(REVISIONS[lesson['slug']])
